#include <string>
using namespace std;

class Solution {
public:
    int concatenateAndMultiplyII(string s) {
        long long MOD = 1000000007;
        string non_zero = "";
        long long S = 0;
        for (char c : s) {
            S = (S + (c - '0')) % MOD;
            if (c != '0') non_zero += c;
        }
        if (non_zero.empty()) return 0;
        long long C = 0;
        for (char c : non_zero) {
            C = (C * 10 + (c - '0')) % MOD;
        }
        return (C * S) % MOD;
    }
};

class Solution {
    public int concatenateAndMultiplyII(String s) {
        long MOD = 1000000007;
        StringBuilder nonZero = new StringBuilder();
        long S = 0;
        for (char c : s.toCharArray()) {
            S = (S + (c - '0')) % MOD;
            if (c != '0') nonZero.append(c);
        }
        if (nonZero.length() == 0) return 0;
        long C = 0;
        for (int i = 0; i < nonZero.length(); i++) {
            C = (C * 10 + (nonZero.charAt(i) - '0')) % MOD;
        }
        return (int)((C * S) % MOD);
    }
}

var concatenateAndMultiplyII = function(s) {
    const MOD = 1000000007n;
    let S = 0n;
    let nonZero = "";
    for (const c of s) {
        S = (S + BigInt(c)) % MOD;
        if (c !== '0') nonZero += c;
    }
    if (nonZero.length === 0) return 0;
    let C = 0n;
    for (const c of nonZero) {
        C = (C * 10n + BigInt(c)) % MOD;
    }
    return Number((C * S) % MOD);
};
